import React, { useState, useCallback } from 'react';
import { useDropzone } from 'react-dropzone';
import toast from 'react-hot-toast';
import { uploadPaymentExcel } from '../services/api';
import { Upload, FileSpreadsheet, CheckCircle, Users, SkipForward, AlertTriangle } from 'lucide-react';

export default function PaymentExcelUpload({ onDataLoaded }) {
  const [file, setFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [summary, setSummary] = useState(null);

  const onDrop = useCallback((accepted) => {
    if (accepted.length) {
      setFile(accepted[0]);
      setSummary(null);
    }
  }, []);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: { 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': ['.xlsx'] },
    maxFiles: 1,
  });

  const handleProcess = async () => {
    if (!file) return toast.error('Please select an Excel file');
    setLoading(true);
    try {
      const res = await uploadPaymentExcel(file);
      const data = res.data.data;
      setSummary(data.summary);
      onDataLoaded(data);
      toast.success(`✅ Processed! ${data.summary.matched} parties ready to email.`);
    } catch (err) {
      const msg = err.response?.data?.message || 'Processing failed';
      toast.error(msg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="upload-section">
      <div
        {...getRootProps()}
        className={`dropzone ${isDragActive ? 'active' : ''} ${file ? 'has-file' : ''}`}
      >
        <input {...getInputProps()} />
        {file ? (
          <div className="dropzone-file">
            <FileSpreadsheet size={32} className="text-green" />
            <span>{file.name}</span>
            <small>{(file.size / 1024).toFixed(1)} KB</small>
          </div>
        ) : (
          <div className="dropzone-empty">
            <Upload size={32} />
            <p>{isDragActive ? 'Drop file here…' : 'Drag & drop Payment Excel, or click to browse'}</p>
            <small>Supports both legacy (2-sheet) and new single-sheet formats</small>
          </div>
        )}
      </div>

      <button
        className="btn btn-primary"
        onClick={handleProcess}
        disabled={loading || !file}
      >
        {loading ? <span className="spinner-sm" /> : <Upload size={16} />}
        {loading ? 'Processing…' : 'Upload & Process'}
      </button>

      {summary && (
        <div className="summary-cards">
          <div className="summary-card green">
            <CheckCircle size={22} />
            <div>
              <div className="summary-num">{summary.matched}</div>
              <div className="summary-label">Ready to Email</div>
            </div>
          </div>
          <div className="summary-card orange">
            <SkipForward size={22} />
            <div>
              <div className="summary-num">{summary.skipped}</div>
              <div className="summary-label">Skipped</div>
            </div>
          </div>
          <div className="summary-card red">
            <AlertTriangle size={22} />
            <div>
              <div className="summary-num">{summary.withoutEmail}</div>
              <div className="summary-label">No Email</div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
